"use client";
import { controlStyles } from "@/components/ui/kalos-styles";
import { slidingHighlightClasses, useSlidingHighlight } from "@/components/ui/kalos-highlight";
import { cn } from "@/lib/utils";
import type { ReactNode } from "react";
import {
  Tabs,
  TabsList,
  TabsTrigger,
  TabsContent,
} from "@/components/ui/kalos-aria-tabs";
export function KalosTabs({
  items,
  defaultValue,
}: {
  items: { value: string; label: string; content: ReactNode }[];
  defaultValue?: string;
}) {
  const highlight = useSlidingHighlight('[role="tab"]', '[role="tab"][aria-selected="true"]');
  return (
    <Tabs defaultSelectedKey={defaultValue || items[0]?.value}>
      <TabsList ref={highlight} aria-label="内容选项卡" className={cn(slidingHighlightClasses, controlStyles.tabsList)}>
        {items.map((item) => (
          <TabsTrigger
            key={item.value}
            id={item.value}
            className={controlStyles.tabsTrigger}
          >
            {item.label}
          </TabsTrigger>
        ))}
      </TabsList>
      {items.map((item) => (
        <TabsContent key={item.value} id={item.value} className="rounded-[7px]">
          {item.content}
        </TabsContent>
      ))}
    </Tabs>
  );
}

"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import {
  TabList as TabListPrimitive,
  TabPanel as TabPanelPrimitive,
  Tab as TabPrimitive,
  Tabs as TabsPrimitive,
} from "react-aria-components";

function Tabs({
  className,
  ...props
}: React.ComponentProps<typeof TabsPrimitive>) {
  return (
    <TabsPrimitive
      data-slot="tabs"
      className={cn(
        "group/tabs flex gap-2 data-horizontal:flex-col",
        className,
      )}
      {...props}
    />
  );
}

const tabsListVariants = cva(
  "group/tabs-list inline-flex w-fit items-center justify-center rounded-[9px] p-[3px] text-muted-foreground group-data-horizontal/tabs:h-8 group-data-vertical/tabs:h-fit group-data-vertical/tabs:flex-col data-[variant=line]:rounded-none",
  {
    variants: {
      variant: {
        default: "bg-muted",
        line: "gap-1 bg-transparent",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

function TabsList({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<typeof TabListPrimitive> &
  VariantProps<typeof tabsListVariants>) {
  return (
    <TabListPrimitive
      data-slot="tabs-list"
      data-variant={variant}
      className={cn(tabsListVariants({ variant }), className)}
      {...props}
    />
  );
}

function TabsTrigger({
  className,
  ...props
}: React.ComponentProps<typeof TabPrimitive>) {
  return (
    <TabPrimitive
      data-slot="tabs-trigger"
      className={cn(
        "relative inline-flex h-[calc(100%-1px)] flex-1 cursor-default items-center justify-center gap-1.5 rounded-[6px] border border-transparent px-3 py-0.5 text-[13px] font-medium whitespace-nowrap text-foreground/60 transition-all outline-none group-data-vertical/tabs:w-full group-data-vertical/tabs:justify-start hover:text-foreground disabled:pointer-events-none disabled:opacity-50 has-data-[icon=inline-end]:pr-1 has-data-[icon=inline-start]:pl-1 data-[disabled]:pointer-events-none data-[disabled]:opacity-50 dark:text-muted-foreground dark:hover:text-foreground group-data-[variant=default]/tabs-list:data-selected:shadow-sm group-data-[variant=line]/tabs-list:data-selected:shadow-none group-data-[variant=default]/tabs-list:data-active:shadow-sm group-data-[variant=line]/tabs-list:data-active:shadow-none [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        "group-data-[variant=line]/tabs-list:bg-transparent group-data-[variant=line]/tabs-list:data-selected:bg-transparent dark:group-data-[variant=line]/tabs-list:data-selected:border-transparent dark:group-data-[variant=line]/tabs-list:data-selected:bg-transparent",
        "data-selected:bg-background data-selected:text-foreground dark:data-selected:border-input dark:data-selected:bg-input/30 dark:data-selected:text-foreground",
        "after:absolute after:bg-foreground after:opacity-0 after:transition-opacity group-data-horizontal/tabs:after:inset-x-0 group-data-horizontal/tabs:after:bottom-[-5px] group-data-horizontal/tabs:after:h-0.5 group-data-vertical/tabs:after:inset-y-0 group-data-vertical/tabs:after:-right-1 group-data-vertical/tabs:after:w-0.5 group-data-[variant=line]/tabs-list:data-selected:after:opacity-100",
        className,
      )}
      {...props}
    />
  );
}

function TabsContent({
  className,
  ...props
}: React.ComponentProps<typeof TabPanelPrimitive>) {
  return (
    <TabPanelPrimitive
      data-slot="tabs-content"
      className={cn("flex-1 text-[13px] outline-none", className)}
      {...props}
    />
  );
}

export { Tabs, TabsList, TabsTrigger, TabsContent, tabsListVariants };

"use client";

import { useCallback, useEffect, useRef } from "react";

export const slidingHighlightClasses = "relative isolate before:pointer-events-none before:absolute before:left-[var(--kalos-highlight-x,0px)] before:top-[var(--kalos-highlight-y,0px)] before:z-0 before:h-[var(--kalos-highlight-height,0px)] before:w-[var(--kalos-highlight-width,0px)] before:rounded-[5px] before:bg-accent before:opacity-[var(--kalos-highlight-opacity,0)] before:transition-[left,top,width,height,opacity] before:duration-200 before:ease-[cubic-bezier(.2,.8,.2,1)] before:content-[''] [&_[role=option]]:relative [&_[role=option]]:z-10 [&_[role=option]]:bg-transparent!";

/** A single background follows the library's own focused/selected item. */
export function useSlidingHighlight(selector: string, activeSelector: string, followPointer = false) {
  const cleanup = useRef<(() => void) | null>(null);
  useEffect(() => () => cleanup.current?.(), []);
  return useCallback((node: HTMLElement | null) => {
    cleanup.current?.();
    cleanup.current = null;
    if (!node) return;
    let frame = 0;
    const position = (item: HTMLElement | null) => {
      if (!item) { node.style.setProperty("--kalos-highlight-opacity", "0"); return; }
      if (!node.contains(item) || item.matches('[aria-disabled="true"], [data-disabled]')) return;
      const root = node.getBoundingClientRect();
      const target = item.getBoundingClientRect();
      const scaleX = node.offsetWidth ? root.width / node.offsetWidth : 1;
      const scaleY = node.offsetHeight ? root.height / node.offsetHeight : 1;
      node.style.setProperty("--kalos-highlight-x", `${(target.left - root.left) / scaleX + node.scrollLeft - node.clientLeft}px`);
      node.style.setProperty("--kalos-highlight-y", `${(target.top - root.top) / scaleY + node.scrollTop - node.clientTop}px`);
      node.style.setProperty("--kalos-highlight-width", `${target.width / scaleX}px`);
      node.style.setProperty("--kalos-highlight-height", `${target.height / scaleY}px`);
      node.style.setProperty("--kalos-highlight-opacity", "1");
    };
    const update = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => position(activeSelector.split(",").map(query => node.querySelector<HTMLElement>(query.trim())).find(Boolean) ?? null));
    };
    const pointer = (event: Event) => {
      if (event.target instanceof Element) position(event.target.closest<HTMLElement>(selector));
    };
    const observer = new MutationObserver(update);
    observer.observe(node, { subtree: true, childList: true, attributes: true, attributeFilter: ["data-highlighted", "data-focused", "data-state", "aria-selected", "aria-activedescendant"] });
    const resize = new ResizeObserver(update);
    resize.observe(node);
    node.addEventListener("scroll", update, true);
    if (followPointer) {
      node.addEventListener("pointermove", pointer);
      node.addEventListener("focusin", pointer);
    }
    update();
    cleanup.current = () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      resize.disconnect();
      node.removeEventListener("scroll", update, true);
      node.removeEventListener("pointermove", pointer);
      node.removeEventListener("focusin", pointer);
    };
  }, [selector, activeSelector, followPointer]);
}
